'use strict';

// These are prompt-contract, mocked-transport and DOM checks. The fixture
// proposals are supplied by this test, not independently generated by a model.
const test = require('node:test');
const assert = require('node:assert/strict');
const Caps = require('../framework/capabilities.js');
const Model = require('../framework/model.js');
const { setup, runtime: Runtime, packs: Packs, plan } = require('./helpers/framework-ui-harness.cjs');

const fresh = () => Runtime.create(Packs.get('rain-lab'));
const note = (id, title, extra = {}) => ({ type: 'memory.upsert', id, title, ...extra });
const weather = { type: 'weather.set', changes: { kind: 'rain', name: '小雨', intensity: 1, paused: false } };
const rows = (operations = [], requestedChanges = []) => ({
  schema: 'her-world-turn-v4', requestedChanges,
  lines: [{ text: '这次的话我听见了。', mode: requestedChanges.length ? 'apply_now' : 'discussion', operations }],
  topic: null
});

async function proposal(state, input, raw) {
  let request;
  const original = JSON.stringify(raw);
  const model = Model.create({ fetch: async (_url, options) => {
    request = JSON.parse(options.body);
    return new Response(JSON.stringify({ choices: [{ message: { content: original }, finish_reason: 'stop' }] }));
  } });
  assert(model.connect('MOCK_ONLY_MEMORY_ATTRIBUTION'));
  try {
    const normalized = await model.request({ context: Runtime.context(state), input });
    assert.equal(JSON.stringify(raw), original, 'the supplied synthetic response is unchanged');
    return { request, normalized };
  } finally { model.disconnect(); }
}

function commit(state, input, operations) {
  const result = Runtime.commit(state, Runtime.propose(state, { text: input }),
    plan(['这次记录已保存。'], [{ afterLine: 0, operations }]));
  assert(result.ok, JSON.stringify(result.error));
  return result.state;
}

function mountSaved(state) {
  const key = 'her-world.framework.v4:rain-lab:1.0.0';
  const raw = JSON.stringify(Runtime.serialize(state), null, 2) + '\n';
  const writes = [], store = new Map([[key, raw]]);
  return { ...setup({ store, writes }), key, raw, writes };
}

function card(r, title) {
  const found = r.ids['memory-list'].children.find(row => row.children[0]?.textContent === '她记作：' + title);
  assert(found, 'missing memory card: ' + title);
  return found;
}

function assertAttribution(row, memory, bodyLabel, kindLabel) {
  assert.equal(row.children[0].tagName, 'H3');
  assert.equal(row.children[0].textContent, '她记作：' + memory.title);
  assert.equal(row.children[1].textContent, bodyLabel + '：' + memory.body);
  assert.equal(row.children[2].textContent, '来源：' + memory.source.text);
  assert(row.children[3].textContent.startsWith('她的归类：' + kindLabel));
}

function historicalLabels() {
  const input = '先下一点小雨吧。';
  // Deliberately retain an old model's overbroad classification. Rendering is
  // allowed to attribute it, not silently repair canonical title/kind/body.
  return commit(fresh(), input, [
    weather,
    note('note_request', '喜欢小雨', { body: input, kind: 'preference', perspective: 'player_report', support: { quote: input } }),
    note('note_interpretation', '窗边的想法', { body: '她觉得小雨可能让窗边更安静。', kind: 'note', perspective: 'character_interpretation' }),
    note('note_weather', '一起调雨', { body: '一起调整了世界里的天气', kind: 'experience', perspective: 'shared_event' })
  ]);
}

test('actual outgoing prompt separates a current request, explicit preference and character categorization', async () => {
  const input = '先下一点小雨吧。';
  const { request } = await proposal(fresh(), input, rows());
  const system = request.messages[0].content;
  for (const text of [
    '一次物理请求只说明玩家现在想做什么，不证明长期偏好、性格或承诺',
    '不支持“喜欢小雨”这个标题或preference分类',
    '确需保留时用note和“当前请求”等中性标题',
    '不因同轮动作抹去明确偏好',
    '不靠两个选择片段相等就判断没有偏好',
    '记忆title和kind都是你的标题与归类',
    '精确引用只能证明body来自原文，不能证明这些归类正确',
    '无法可靠区分时不新增偏好判断'
  ]) assert(system.includes(text), text);
  const definition = JSON.parse(system.split('\n本轮内容与能力定义：\n')[1]);
  const descriptor = definition.capabilities.find(item => item.id === 'memory.upsert');
  for (const text of [
    'A present action request is not evidence of an enduring preference.',
    'use kind note and a neutral current-request title',
    'An explicit preference plus an action may retain its preference',
    'Equal request/report spans do not prove absence of a preference.',
    'Titles and kinds are character-authored categorization; quote fidelity does not certify them.'
  ]) assert(descriptor.description.includes(text), text);
  assert.equal(JSON.parse(request.messages[1].content).playerSaid, input);
});

test('legacy memory descriptors retain their exact fields and wording; current guidance adds no schema field', () => {
  const legacy = {
    id: 'memory.upsert',
    description: 'Create or revise a note (maximum14 current notes; title60, body240 characters). Its original source is retained separately from its current revision. Reuse the ID for corrections.',
    schema: {
      type: 'object', additionalProperties: false,
      properties: {
        type: { const: 'memory.upsert' },
        id: { type: 'string', minLength: 1, maxLength: 37, pattern: '^note_[a-z0-9_]{1,32}$' },
        title: { type: 'string', minLength: 1, maxLength: 60 },
        body: { type: 'string', minLength: 1, maxLength: 240 }
      },
      required: ['type', 'id', 'title', 'body']
    }
  };
  for (const version of ['2', '3']) assert.deepEqual(Caps.descriptors(['memory.upsert'], version), [legacy]);
  const current = Caps.descriptors(['memory.upsert'], '4')[0];
  assert.deepEqual(Object.keys(current.schema.properties), ['type', 'id', 'title', 'body', 'kind', 'perspective', 'support']);
  assert.deepEqual(current.schema.required, ['type', 'id', 'title']);
  assert.deepEqual(current.schema.anyOf, [
    { required: ['perspective', 'support'], properties: { perspective: { const: 'player_report' }, body: false } },
    { required: ['body'], properties: { perspective: { type: 'string', enum: ['character_interpretation', 'shared_event'] } } }
  ]);
});

test('a supplied neutral action-request report keeps its exact source and note category through the adapter', async () => {
  const state = fresh(), input = '先下一点小雨吧。';
  const raw = rows([weather, note('note_request', '当前请求', {
    kind: 'note', perspective: 'player_report', support: { quote: input }
  })], [{ domain: 'weather', support: { quote: input } }]);
  const { normalized } = await proposal(state, input, raw);
  const operation = normalized.beats[0].operations[1];
  assert.equal(operation.title, '当前请求');
  assert.equal(operation.kind, 'note');
  assert.equal(operation.body, input);
  assert.equal(Object.hasOwn(raw.lines[0].operations[1], 'body'), false);
  const result = Runtime.commit(state, Runtime.propose(state, { text: input }), normalized);
  assert(result.ok, JSON.stringify(result.error));
  assert.equal(result.state.memories[0].body, input);
  assert.equal(result.state.memories[0].source.text, input);
  assert.equal(result.state.memories[0].kind, 'note');
  assert.equal(result.state.world.weather.source.text, input);
});

test('explicit preference plus action survives both clause support and equal whole-compound spans', async () => {
  const input = '我喜欢小雨，请下一点小雨。';
  for (const [reportQuote, requestQuote] of [['我喜欢小雨', '请下一点小雨'], [input, input]]) {
    const state = fresh();
    const raw = rows([weather, note('note_rain', '小雨的偏好', {
      kind: 'preference', perspective: 'player_report', support: { quote: reportQuote }
    })], [{ domain: 'weather', support: { quote: requestQuote } }]);
    const { normalized } = await proposal(state, input, raw);
    const result = Runtime.commit(state, Runtime.propose(state, { text: input }), normalized);
    assert(result.ok, JSON.stringify(result.error));
    const memory = result.state.memories[0];
    assert.equal(memory.kind, 'preference', 'action/report span equality must not erase a supplied genuine preference');
    assert.equal(memory.title, '小雨的偏好');
    assert.equal(memory.body, reportQuote);
    assert.equal(memory.support.quote, reportQuote);
    assert.equal(memory.source.text, input);
    assert.equal(result.state.world.weather.source.text, input);
    assert.deepEqual(Runtime.restore(Runtime.serialize(result.state), state.pack).state, result.state);
  }
});

test('actual next request retains saved categorization beside the exact player and event sources', async () => {
  const state = historicalLabels();
  const { request } = await proposal(state, '说说现在的窗外。', rows());
  const context = JSON.parse(request.messages[1].content).context;
  assert.equal(context.memories.length, 3);
  for (const memory of state.memories) {
    const supplied = context.memories.find(item => item.title === memory.title);
    assert(supplied);
    for (const field of ['title', 'kind', 'body', 'perspective', 'source', 'currentRevision', 'support']) {
      assert.deepEqual(supplied[field], memory[field], field);
    }
  }
  assert.deepEqual(context.memories[2].eventSupport, state.memories[2].eventSupport);
  assert.equal(context.memories[0].kind, 'preference', 'guidance does not claim to classify or rewrite historical semantics');
});

test('memory cards attribute report, interpretation and actual event without changing historical data or saved bytes', () => {
  const state = historicalLabels(), canonical = Runtime.serialize(state), memories = structuredClone(state.memories);
  const r = mountSaved(state);
  try {
    const labels = [['你的原话', '偏好'], ['她的理解，可被纠正', '记下的片段'], ['已发生的世界变化', '共同经历']];
    for (const [index, memory] of memories.entries()) assertAttribution(card(r, memory.title), memory, ...labels[index]);
    assert.equal(r.ids['memory-count'].textContent, '03');
    r.app.selectPanel('memory');
    r.app.selectPanel('world');
    r.app.selectPanel('memory');
    assert.deepEqual(r.app.snapshot().state.memories, memories);
    assert.deepEqual(Runtime.serialize(r.app.snapshot().state), canonical);
    assert.equal(r.store.get(r.key), r.raw);
    assert.deepEqual(r.writes, []);
    assert.equal(r.model.calls(), 0);
  } finally { r.app.destroy(); }
  const restored = setup({ store: r.store });
  try {
    assertAttribution(card(restored, memories[0].title), memories[0], '你的原话', '偏好');
    assert.deepEqual(restored.app.snapshot().state.memories, memories);
    assert.equal(restored.store.get(r.key), r.raw);
  } finally { restored.app.destroy(); }
});

test('revised report labels its current quote while original source and revision remain separate and unchanged', () => {
  const original = '我喜欢阴天。', correction = '我改主意了，我更喜欢晴天。', quote = '我更喜欢晴天';
  let state = commit(fresh(), original, [note('note_sky', '天气偏好', {
    body: original, kind: 'preference', perspective: 'player_report', support: { quote: original }
  })]);
  const handle = Runtime.context(state).memories[0].id;
  state = commit(state, correction, [note(handle, '新的偏好', {
    body: quote, kind: 'preference', perspective: 'player_report', support: { quote }
  })]);
  const canonical = Runtime.serialize(state), memory = structuredClone(state.memories[0]), r = mountSaved(state);
  try {
    const row = card(r, '新的偏好');
    assertAttribution(row, memory, '你的原话', '偏好');
    assert.equal(row.children[4].textContent, '修订 2：' + correction);
    assert.equal(memory.source.text, original);
    assert.equal(memory.currentRevision.text, correction);
    assert.equal(memory.currentRevision.number, 2);
    assert.deepEqual(r.app.snapshot().state.memories[0], memory);
    assert.deepEqual(Runtime.serialize(r.app.snapshot().state), canonical);
    assert.equal(r.store.get(r.key), r.raw);
    assert.deepEqual(r.writes, []);
  } finally { r.app.destroy(); }
});
